```cpp
#include <iostream>
#include <vector>
using namespace std;
void sieveOfEratosthenes(int n) {
    vector<bool> primes(n+1, true); // create a boolean vector of size n+1 and initialize all values to true
    for (int p=2; p*p<=n; p++) { // loop through all numbers from 2 to sqrt(n)
        if (primes[p] == true) { // if p is prime
            for (int i=p*p; i<=n; i+=p) { // mark all multiples of p as composite
                primes[i] = false;
            }
        }
    }
    // print all prime numbers
    for (int p=2; p<=n; p++) {
        if (primes[p]) {
            cout << p << " ";
        }
    }
}
int main() {
    int n = 10;
    sieveOfEratosthenes(n);
    return 0;
}
```
