```csharp
using System;
using System.Data;
using System.Data.SqlClient;
namespace GraduationDataReport
{
    class Program
    {
        static void Main(string[] args)
        {
            // Connect to the graduation_data table in the XYZ School District database
            SqlConnection connection = new SqlConnection("Data Source=xyz_school_district.db");
            connection.Open();
            SqlCommand command = new SqlCommand();
            command.Connection = connection;
            // Execute the SQL query to retrieve the required data
            command.CommandText = @"
            SELECT COUNT(*) AS total_graduates, gender, ethnicity, 
                   AVG(honors_awards_received) AS percentage_honors_awards
            FROM graduation_data
            WHERE year = '2021'
            GROUP BY gender, ethnicity
            ORDER BY gender, ethnicity";
            SqlDataAdapter adapter = new SqlDataAdapter(command);
            DataTable table = new DataTable();
            adapter.Fill(table);
            // Clean the data
            table.Columns["total_graduates"].ColumnName = "Total Graduates";
            table.Columns["gender"].ColumnName = "Gender";
            table.Columns["ethnicity"].ColumnName = "Ethnicity";
            table.Columns["percentage_honors_awards"].ColumnName = "Percentage of Honors and Awards";
            table.Columns["Percentage of Honors and Awards"].Expression = "Round([Percentage of Honors and Awards] * 100, 2)";
            // Generate the report
            string report = "XYZ School District Graduation Data Report for the year 2021\n\n";
            report += "Total Graduates: " + table.Compute("Sum([Total Graduates])", "") + "\n\n";
            report += "Graduates by Gender and Ethnicity:\n" + DataTableToString(table) + "\n\n";
            report += "Percentage of Students Honored or Awarded: " + table.Compute("Avg([Percentage of Honors and Awards])", "") + "%\n\n";
            // Print the report
            Console.WriteLine(report);
            Console.ReadLine();
        }
        static string DataTableToString(DataTable table)
        {
            string result = "";
            foreach (DataColumn column in table.Columns)
            {
                result += column.ColumnName + "\t";
            }
            result += "\n";
            foreach (DataRow row in table.Rows)
            {
                foreach (DataColumn column in table.Columns)
                {
                    result += row[column] + "\t";
                }
                result += "\n";
            }
            return result;
        }
    }
}
```
