using System.Linq;
using Microsoft.ML;
using Microsoft.ML.Data;
namespace LiteraryTechniques
{
    class Program
    {
        static void Main(string[] args)
        {
            // Step 1: Load data
            var mlContext = new MLContext();
            var dataView = mlContext.Data.LoadFromTextFile<Chapter>(
                "ulysses.csv", separatorChar: ',', hasHeader: true);
            // Step 2: Preprocess data
            var pipeline = mlContext.Transforms.Text
                .FeaturizeText("Features", nameof(Chapter.Text))
                .Append(mlContext.Transforms.Conversion
                    .MapValueToKey("Label", nameof(Chapter.Techniques)))
                .Append(mlContext.Transforms.NormalizeMinMax(
                    "Features", "Features"))
                .Append(mlContext.Transforms.Conversion
                    .MapKeyToValue("PredictedTechniques", "PredictedLabel"));
            // Step 3: Train a machine learning model
            var trainer = mlContext.MulticlassClassification
                .Trainers.SdcaNonCalibrated();
            var trainingPipeline = pipeline
                .Append(trainer)
                .Append(mlContext.Transforms.Conversion
                    .MapKeyToValue("PredictedTechniques", "PredictedLabel"));
            var model = trainingPipeline.Fit(dataView);
            // Step 4: Evaluate the model
            var predictions = model.Transform(dataView);
            var metrics = mlContext.MulticlassClassification
                .Evaluate(predictions, "Label", "Score");
