            };
            var chapter2 = new Chapter
            {
                ChapterNumber = 2,
                Text = "Ineluctable modality of the visible: at least that if no more, thought through my eyes."
            };
            var predictor = mlContext.Model.CreatePredictionEngine<Chapter, Prediction>(model);
            var prediction1 = predictor.Predict(chapter1);
            var prediction2 = predictor.Predict(chapter2);
            Console.WriteLine($"Chapter 1: {string.Join(", ", prediction1.PredictedTechniques)}");
